export function validateText(text) {
  if (typeof text !== 'string' || !text.trim() || text.trim().length > 4000)
    throw new Error('text must be a string containing 1–4000 characters');
  return text.trim();
}
export function validateTags(tags = []) {
  if (!Array.isArray(tags)) throw new Error('tags must be an array');
  return [...new Set(tags.map(tag => {
    if (typeof tag !== 'string' || !tag.trim() || tag.trim().length > 40)
      throw new Error('tags must contain nonempty strings of at most 40 characters');
    return tag.trim().toLowerCase();
  }))].sort();
}
export function validateId(id) {
  if (!Number.isSafeInteger(id) || id < 1) throw new Error('id must be a positive integer');
  return id;
}
export function validateObject(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('expected an object');
  return value;
}

import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { validateText, validateTags, validateId, validateObject } from './validation.mjs';

export function openStore(path) {
  mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000;
    CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,text TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS tags(name TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS note_tags(note_id INTEGER REFERENCES notes(id) ON DELETE CASCADE,tag TEXT REFERENCES tags(name),PRIMARY KEY(note_id,tag));`);
  db.function('fold', value => value.toLowerCase());
  let depth = 0;
  const transaction = fn => {
    if (depth) return fn();
    db.exec('BEGIN IMMEDIATE'); depth++;
    try { const result = fn(); db.exec('COMMIT'); return result; }
    catch (error) { db.exec('ROLLBACK'); throw error; }
    finally { depth--; }
  };
  const getNote = id => {
    validateId(id);
    const row = db.prepare('SELECT * FROM notes WHERE id=?').get(id);
    if (!row) return null;
    return { id: Number(row.id), text: row.text, createdAt: row.created_at, updatedAt: row.updated_at,
      tags: db.prepare('SELECT tag FROM note_tags WHERE note_id=? ORDER BY tag').all(id).map(r => r.tag) };
  };
  const attachTags = (id, tags) => {
    for (const tag of tags) {
      db.prepare('INSERT OR IGNORE INTO tags VALUES(?)').run(tag);
      db.prepare('INSERT INTO note_tags VALUES(?,?)').run(id, tag);
    }
  };
  return {
    transaction,
    createNote(text, tags = []) {
      text = validateText(text); tags = validateTags(tags);
      return transaction(() => {
        const now = new Date().toISOString();
        const id = Number(db.prepare('INSERT INTO notes(text,created_at,updated_at) VALUES(?,?,?)').run(text, now, now).lastInsertRowid);
        attachTags(id, tags); return getNote(id);
      });
    },
    getNote,
    listNotes({ q, tag, limit = 50, offset = 0 } = {}) {
      if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('limit must be an integer from 1 to 100');
      if (!Number.isSafeInteger(offset) || offset < 0) throw new Error('offset must be a nonnegative integer');
      if (q !== undefined && typeof q !== 'string') throw new Error('q must be a string');
      if (tag !== undefined) tag = validateTags([tag])[0];
      return db.prepare(`SELECT id FROM notes WHERE (? IS NULL OR instr(fold(text),fold(?))>0)
        AND (? IS NULL OR EXISTS(SELECT 1 FROM note_tags WHERE note_id=notes.id AND tag=?))
        ORDER BY id DESC LIMIT ? OFFSET ?`).all(q ?? null, q ?? null, tag ?? null, tag ?? null, limit, offset).map(r => getNote(Number(r.id)));
    },
    updateNote(id, patch) {
      validateId(id); validateObject(patch);
      const text = Object.hasOwn(patch, 'text') ? validateText(patch.text) : undefined;
      const tags = Object.hasOwn(patch, 'tags') ? validateTags(patch.tags) : undefined;
      return transaction(() => {
        const old = getNote(id); if (!old) return null;
        const now = new Date(Math.max(Date.now(), Date.parse(old.updatedAt) + 1)).toISOString();
        db.prepare('UPDATE notes SET text=?,updated_at=? WHERE id=?').run(text ?? old.text, now, id);
        if (tags !== undefined) { db.prepare('DELETE FROM note_tags WHERE note_id=?').run(id); attachTags(id, tags); }
        return getNote(id);
      });
    },
    deleteNote(id) { validateId(id); return db.prepare('DELETE FROM notes WHERE id=?').run(id).changes > 0; },
    listTags() { return db.prepare('SELECT tag AS name,COUNT(*) AS count FROM note_tags GROUP BY tag ORDER BY tag').all().map(r => ({ name: r.name, count: Number(r.count) })); },
    close() { db.close(); }
  };
}

import { validateText, validateTags, validateObject } from './validation.mjs';

export function importNotes(store, records) {
  if (!Array.isArray(records)) throw new Error('notes must be an array');
  const prepared = records.map(record => {
    validateObject(record);
    return { text: validateText(record.text), tags: validateTags(record.tags) };
  });
  const write = () => prepared.map(record => store.createNote(record.text, record.tags));
  return store.transaction ? store.transaction(write) : write();
}

import { importNotes } from './import.mjs';
import { validateObject } from './validation.mjs';

export function allNotes(store) {
  const notes = [];
  for (let offset = 0; ; offset += 100) {
    const page = store.listNotes({ limit: 100, offset });
    notes.push(...page);
    if (page.length < 100) return notes;
  }
}
export function exportNotes(store) {
  return { version: 1, notes: allNotes(store).reverse().map(({ text, tags }) => ({ text, tags })) };
}
const string = { type: 'string' }, id = { type: 'integer', minimum: 1 };
const tags = { type: 'array', items: { type: 'string', minLength: 1, maxLength: 40 } };
const note = { type: 'object', properties: { text: { ...string, minLength: 1, maxLength: 4000 }, tags }, required: ['text'], additionalProperties: false };
export const tools = [
  ['notes_create', 'Create a note', note.properties, ['text']],
  ['notes_get', 'Get a note', { id }, ['id']],
  ['notes_list', 'Search and list notes', { q: string, tag: string, limit: { type: 'integer', minimum: 1, maximum: 100 }, offset: { type: 'integer', minimum: 0 } }, []],
  ['notes_update', 'Update a note', { id, ...note.properties }, ['id']],
  ['notes_delete', 'Delete a note', { id }, ['id']],
  ['tags_list', 'List tag counts', {}, []],
  ['notes_export', 'Export notes oldest first', {}, []],
  ['notes_import', 'Import a validated batch', { notes: { type: 'array', items: note } }, ['notes']]
].map(([name, description, properties, required]) => ({ name, description, inputSchema: { type: 'object', properties, required, additionalProperties: false } }));
export function callTool(store, name, args = {}) {
  validateObject(args);
  const descriptor = tools.find(tool => tool.name === name);
  if (!descriptor) throw new Error('Unknown tool');
  for (const key of descriptor.inputSchema.required) if (!Object.hasOwn(args, key)) throw new Error(`Missing ${key}`);
  for (const key of Object.keys(args)) if (!Object.hasOwn(descriptor.inputSchema.properties, key)) throw new Error(`Unknown argument ${key}`);
  switch (name) {
    case 'notes_create': return store.createNote(args.text, args.tags);
    case 'notes_get': return store.getNote(args.id);
    case 'notes_list': return store.listNotes(args);
    case 'notes_update': { const { id, ...patch } = args; return store.updateNote(id, patch); }
    case 'notes_delete': return store.deleteNote(args.id);
    case 'tags_list': return store.listTags();
    case 'notes_export': return exportNotes(store);
    case 'notes_import': return importNotes(store, args.notes);
  }
}

import { createInterface } from 'node:readline';
import { parseArgs } from 'node:util';
import { openStore } from './store.mjs';
import { tools, callTool, allNotes } from './service.mjs';

const { values } = parseArgs({ options: { db: { type: 'string', default: 'data/notes.sqlite' } } });
const store = openStore(values.db);
const input = createInterface({ input: process.stdin, crlfDelay: Infinity });
const resource = { uri: 'notes://all', name: 'All notes', mimeType: 'application/json' };
function dispatch(method, params = {}) {
  switch (method) {
    case 'initialize': return { protocolVersion: '2024-11-05', capabilities: { tools: {}, resources: {} }, serverInfo: { name: 'quick-notes', version: '1.0.0' } };
    case 'notifications/initialized': return {};
    case 'ping': return {};
    case 'tools/list': return { tools };
    case 'tools/call':
      try { return { content: [{ type: 'text', text: JSON.stringify(callTool(store, params.name, params.arguments)) }] }; }
      catch (error) { return { isError: true, content: [{ type: 'text', text: error.message }] }; }
